import unreal
import json
paths = ['/Game/_Game/Blueprints/BP_Joaquin_Player.BP_Joaquin_Player','/Game/_Game/Blueprints/BP_Sombra_NPC.BP_Sombra_NPC','/Game/_Game/Blueprints/GM_ShadowTown.GM_ShadowTown']
for p in paths:
